import {shell,mount,esc,toast} from './components.js';
import {read,write,clone,selectFinal,boardStale,makeShots,changed,applyReport,validateReport,taskSnapshot} from './workflow-store.js';
import {settingsMarkup,bindSettings} from './workflow-settings.js';
const s=read(),page=document.body.dataset.page;let openSettings,busy=false,previewTimer;
const $=id=>document.getElementById(id);
function persist(){try{write(s);return true}catch{toast('本地保存失败，内容仍在当前页。请减少上传文件后重试，暂勿离开。');return false}}
const action=(id,fn)=>{const e=$(id);if(e)e.onclick=fn};
function nav(){return `<div class="stepnav" aria-label="创作进度"><a href="./script.html" data-nav="script" class="${page==='script'?'current':''}">01 剧本创作</a><span>→</span><a href="./storyboard.html" data-nav="storyboard" class="${page==='storyboard'?'current':''}">02 分镜与制作</a><span>→</span><a href="./finishing.html" data-nav="finishing" class="${page==='finishing'?'current':''}">03 成片与导出</a></div>`}
function render(){const content=page==='script'?scriptPage():page==='storyboard'?boardPage():finishPage();mount(shell({active:page,content:nav()+content+settingsMarkup()+`<dialog class="dialog wide-dialog" id="review-dialog" aria-labelledby="review-title"></dialog><dialog class="dialog" id="confirm-dialog" aria-labelledby="confirm-title"></dialog>`}));document.querySelector('.app-shell').classList.add('workflow');openSettings=bindSettings(s,persist,render);document.querySelectorAll('[data-config]').forEach(b=>b.onclick=()=>openSettings(b.dataset.config,b.dataset.step||({script:'script',storyboard:'storyboard',finishing:'voice'}[page])));if(page==='script')bindScript();else if(page==='storyboard')bindBoard();else bindFinish();}
function confirmAction(title,description,fn){const d=$('confirm-dialog');d.innerHTML=`<h2 id="confirm-title">${esc(title)}</h2><p>${esc(description)}</p><div class="dialog-footer"><button class="button" id="cancel-confirm">保留当前内容</button><button class="button primary" id="accept-confirm">确认继续</button></div>`;action('cancel-confirm',()=>d.close());action('accept-confirm',()=>{d.close();fn()});d.showModal();}
function scriptPage(){return `<div class="page-heading"><div><p class="eyebrow">一句话 → 短片 / 01</p><h1>先把创意，写成值得拍的剧本</h1><p>与 AI 探讨不同版本，加入备选后选定一版，再进入分镜。</p></div><span class="pill">本地原型 · AI 输出为示例</span></div><section class="panel section" id="idea-panel"><div class="field-pair"><label class="field">作品名称<input id="flow-title" type="text" value="${esc(s.title)}"></label><div class="row"><span class="pill">60 秒 · 9:16 竖屏</span><span class="helper">目标默认值，成片页可调整镜头时长</span></div></div><label class="field">一句话创意<textarea id="flow-idea">${esc(s.idea)}</textarea></label><div class="row"><button class="button primary" id="generate-first">${s.scripts.length?'根据创意再生成一版':'生成第一版剧本'}</button><button class="button" data-config="prompts" data-step="script">剧本提示词</button><span class="helper" id="script-save-status">输入保存在本浏览器演示空间</span></div></section><div class="workspace-grid"><section class="panel" id="script-chat"><div class="panel-header"><h2>AI 剧本对话</h2><span class="pill">${s.scripts.length} 个版本</span></div><div class="chat-scroll" id="chat-scroll">${s.scripts.length?s.scripts.map((v,i)=>`<article class="script-card"><p class="helper">你：${esc(v.instruction)}</p><div class="panel-header"><strong>AI 剧本 v${i+1}</strong><span class="pill">示例生成</span></div><label class="field">剧本 v${i+1} 内容<textarea data-script-edit="${v.id}">${esc(v.text)}</textarea></label><p class="helper">可人工编辑；加入备选时保存当前内容副本。</p><button class="button" data-shortlist="${v.id}">＋ 加入备选</button></article>`).join(''):'<div class="notice">在上方输入创意，生成第一版完整剧本后，可在此继续讨论。</div>'}</div><label class="field">继续与 AI 探讨<textarea id="script-instruction" placeholder="例如：让结尾更温暖，补充取件动作，减少旁白。">${esc(s.instruction)}</textarea></label><div class="row"><button class="button primary" id="generate-next" ${s.scripts.length?'':'disabled'}>发送并生成新版本</button><span class="helper">保留所有已有版本</span></div></section><aside class="panel" id="candidate-zone"><div class="panel-header"><h2>剧本备选区</h2><span class="pill">${s.candidates.length} 份备选</span></div>${s.candidates.length?s.candidates.map((v,i)=>`<article class="candidate ${s.final?.id===v.id?'selected':''}"><div class="panel-header"><strong>备选 ${i+1} · 来自 v${v.sourceVersion}</strong><span class="pill ${s.final?.id===v.id?'success':''}">${s.final?.id===v.id?'已选定终版':'待选择'}</span></div><p>${esc(v.text)}</p><div class="row"><button class="button ${s.final?.id===v.id?'':'primary'}" data-select-final="${v.id}" ${s.final?.id===v.id?'disabled':''}>${s.final?.id===v.id?'当前终版':'选定为终版'}</button><button class="button" data-remove-candidate="${v.id}" ${s.final?.id===v.id?'disabled':''}>移出备选</button></div></article>`).join(''):'<div class="notice">从对话中的剧本点击“加入备选”，在这里比较与选定。</div>'}<div id="final-next">${s.final?`<div class="notice success">已选定剧本 ${esc(s.final.id)}。后续分镜以这份内容为输入。</div><a class="button primary" href="./storyboard.html" data-nav="storyboard">进入独立分镜页 →</a>`:'<button class="button" disabled>选定剧本后进入分镜</button>'}</div></aside></div>`}
function generateScript(instruction){if(busy)return;if(!s.idea.trim()){toast('请先填写一句话创意');$('flow-idea').focus();return;}busy=true;const b=$('generate-next');b.disabled=true;$('generate-first').disabled=true;toast('正在生成剧本示例…');const snapshot=taskSnapshot(s,'script');const inputIdea=s.idea;setTimeout(()=>{const n=s.scripts.length+1;const rain=inputIdea.includes('快递')||inputIdea.includes('雨夜');const scenes=rain?['【开场 0–20秒】雨夜，快递员停在旧街巷。他擦去头盔上的雨水，认出了老师家的门牌。快递员低声说：“这个地址，我还记得。”','【发展 20–40秒】他从车后取出被雨衣护住的包裹，走到门口。老师开门，他双手递出包裹：“老师，您的包裹。”老师认出他，眼神由疑惑转为欣慰。','【结尾 40–60秒】老师递来一条干毛巾，轻声说：“进来躲躲雨吧。”快递员笑着点头：“谢谢您，我一直记得。”暖光照亮两人，雨声渐轻。']:[`【开场 0–20秒】围绕“${inputIdea}”建立主角目标：主角在现场发现问题，以一个可见动作开始尝试。`,`【发展 20–40秒】主角遇到阻碍，停顿观察后主动改变方法；用行动和一句关键台词呈现转折。`,`【结尾 40–60秒】主角完成行动，画面回应开场目标，以人物反应收束故事。`];s.scripts.push({id:`script-${Date.now()}`,instruction,text:`创意：${inputIdea}\n${scenes.join('\n')}\n本版创作要求：${instruction}${n>1?'；本版提供可人工编辑的讨论稿。':''}`,snapshot});busy=false;persist();render();toast(`剧本 v${n} 已生成，可编辑并加入备选。AI 内容为交互示例。`)},550);}
function bindScript(){for(const [id,key]of [['flow-title','title'],['flow-idea','idea'],['script-instruction','instruction']])$(id).oninput=e=>{s[key]=e.target.value;persist()};action('generate-first',()=>generateScript('按当前创意生成完整剧本'));action('generate-next',()=>{if(!s.instruction.trim()){toast('请先输入本轮讨论或调整要求');return}generateScript(s.instruction)});document.querySelectorAll('[data-script-edit]').forEach(e=>e.oninput=()=>{s.scripts.find(v=>v.id===e.dataset.scriptEdit).text=e.value;persist()});document.querySelectorAll('[data-shortlist]').forEach(b=>b.onclick=()=>{const v=s.scripts.find(x=>x.id===b.dataset.shortlist);if(!v.text.trim()){toast('空剧本不能加入备选');return}if(s.candidates.some(c=>c.sourceId===v.id&&c.text===v.text)){toast('这一版内容已在备选区');return}s.candidates.push({id:`candidate-${Date.now()}`,sourceId:v.id,sourceVersion:s.scripts.indexOf(v)+1,text:v.text,snapshot:clone(v.snapshot)});persist();render();toast('当前剧本副本已加入备选')});document.querySelectorAll('[data-select-final]').forEach(b=>b.onclick=()=>{const v=s.candidates.find(x=>x.id===b.dataset.selectFinal);const pick=()=>{selectFinal(s,v);persist();render();toast('已选定终版；分镜将使用此版本')};if(s.shots.length)confirmAction('更换剧本终版？','已有分镜、图片和视频会保留，但分镜来源将标为过期，需按新终版重新生成和质检。',pick);else pick()});document.querySelectorAll('[data-remove-candidate]').forEach(b=>b.onclick=()=>{s.candidates=s.candidates.filter(x=>x.id!==b.dataset.removeCandidate);persist();render()});}
function assetMarkup(a,i,j){return `<div class="asset-item compact-asset"><strong>${a.kind} · ${esc(a.name)}</strong>${a.image?`<img src="${esc(a.image)}" alt="${esc(a.kind+' '+a.name)}">`:'<div class="placeholder">暂无参考图</div>'}<div class="row"><button class="button" data-asset-generate="${i}:${j}">AI 生图</button><button class="button" data-manage-asset="${i}:${j}">设置/上传</button></div><span class="helper">${a.confirmed?'已确认选用':a.image?'待确认选用':'生成或上传已有图'}</span></div>`}
function boardPage(){return `<div class="page-heading"><div><p class="eyebrow">一句话 → 短片 / 02</p><h1>分镜工作台</h1><p>逐镜编辑台词、素材、提示词与视频；随时对照选定剧本质检。</p></div><span class="pill">${s.shots.length} 个镜头 · 分镜 v${s.boardVersion}</span></div>${!s.final?'<section class="panel"><h2>尚未选定剧本</h2><p>先在剧本备选区选定终版，分镜才能获得明确输入。</p><a class="button primary" href="./script.html" data-nav="script">返回剧本创作</a></section>':`${boardStale(s)?'<div class="notice warning">剧本终版已更换。当前分镜来自旧剧本，生成与确认已暂停，请按新终版重新生成分镜。</div>':''}<details id="source-script"><summary>查看选定剧本 · 备选 ${s.candidates.findIndex(c=>c.id===s.final.id)+1} / 剧本 v${s.final.sourceVersion}</summary><div class="notice" style="white-space:pre-wrap">${esc(s.final.text)}</div></details><div class="toolbar" id="board-toolbar"><button class="button primary" id="generate-board">${s.shots.length?'重新生成分镜':'从选定剧本生成分镜'}</button><button class="button" id="run-review" ${!s.shots.length||boardStale(s)?'disabled':''}>AI 分镜质检</button><button class="button" id="view-report" ${s.report?'':'disabled'}>查看质检报告</button><button class="button" data-config="prompts" data-step="storyboard">分镜提示词</button><button class="button" data-config="styles">风格：${esc(s.styles[s.styleIndex].name)}</button><span class="spacer"></span><button class="button" id="confirm-board" ${!s.report||s.report.baseBoardVersion!==s.boardVersion||s.report.issues.length||boardStale(s)?'disabled':''}>${s.boardConfirmed===s.boardVersion&&s.shots.length?'分镜已确认':'确认当前分镜'}</button></div><div class="notice ${s.boardConfirmed===s.boardVersion&&s.shots.length?'success':''}" id="board-state">${s.boardConfirmed===s.boardVersion&&s.shots.length?'当前分镜已人工确认。可逐项生成或上传参考图，确认选用后生成视频。':s.report?.baseBoardVersion!==s.boardVersion&&s.report?'分镜已改动，旧质检报告不可继续采用。请重新质检。':'顺序：生成分镜 → 质检与调整 → 确认分镜 → 确认参考图 → 生成视频。'}</div>${s.shots.length?`<div class="board-scroll" id="storyboard-table"><table class="board"><colgroup><col style="width:58px"><col style="width:240px"><col style="width:185px"><col style="width:350px"><col style="width:180px"><col style="width:105px"></colgroup><thead><tr><th>序号</th><th>台词</th><th>角色 / 场景 / 道具</th><th>提示词</th><th>视频</th><th>操作</th></tr></thead><tbody>${s.shots.map((sh,i)=>`<tr id="row-${sh.id}"><td title="${esc(sh.id)}">${i+1}</td><td><label class="field">说话角色<input type="text" data-shot-field="${i}:speaker" value="${esc(sh.speaker)}"></label><label class="field">情绪<input type="text" data-shot-field="${i}:emotion" value="${esc(sh.emotion)}"></label><label class="field">镜头 ${i+1} 台词<textarea data-shot-field="${i}:dialogue">${esc(sh.dialogue)}</textarea></label><div class="row"><button class="button" data-ai-dialogue="${i}">AI 生成台词</button><button class="button" data-config="prompts" data-step="dialogue">提示词</button></div></td><td>${sh.assets.map((a,j)=>assetMarkup(a,i,j)).join('')}<button class="button" data-config="prompts" data-step="image">生图提示词</button></td><td><label class="field">镜头 ${i+1} 提示词<textarea class="prompt-edit" data-shot-field="${i}:prompt">${esc(sh.prompt)}</textarea></label><div class="row"><button class="button" data-ai-prompt="${i}">AI 生成提示词</button><button class="button" data-config="prompts" data-step="shotPrompt">提示词设置</button></div><label class="field">时长（秒）<input type="number" min="1" max="90" data-shot-field="${i}:duration" value="${sh.duration}"></label></td><td><div class="video-slot">${sh.video?.data?`<video src="${esc(sh.video.data)}" controls></video>`:sh.video?'<strong>视频生成示例</strong><span class="helper">已完成演示<br>非真实视频文件</span>':'<span>暂无视频</span>'}</div>${sh.videoStale?'<p class="error-text">素材已变更，视频待更新</p>':''}<button class="button primary" data-generate-video="${i}" ${s.boardConfirmed!==s.boardVersion||boardStale(s)||sh.assets.some(a=>!a.confirmed)?'disabled':''}>${sh.video?'重新生成':'生成视频'}</button><label class="button upload">上传视频<input type="file" accept="video/mp4,video/webm" data-video-upload="${i}" aria-label="上传镜头 ${i+1} 视频" hidden></label><button class="button" data-config="prompts" data-step="video">视频提示词</button></td><td><div class="stack"><button class="button" data-move="${i}:-1" ${i===0?'disabled':''}>上移</button><button class="button" data-move="${i}:1" ${i===s.shots.length-1?'disabled':''}>下移</button><button class="button" data-add="${i}">向下添加</button><button class="button danger" data-delete="${i}" ${s.shots.length===1?'disabled':''}>删除</button></div></td></tr>`).join('')}</tbody></table></div><div class="row section" style="margin-top:20px"><a class="button" href="./script.html" data-nav="script">← 返回剧本备选</a><a class="button primary" href="./finishing.html" data-nav="finishing">进入成片与导出 →</a><span class="helper">成片页会检查分镜确认、视频缺失及过期状态。</span></div>`:'<section class="panel"><h2>把选定剧本拆为可制作的镜头</h2><p>生成后在此展示独立分镜表，不与剧本对话拼成长页。</p></section>'}`}`}
function editShot(i){const sh=s.shots[i];sh.videoStale=!!sh.video;sh.assets.forEach(a=>a.confirmed=false);changed(s);persist();$('board-state').textContent='分镜已编辑；旧审核和确认失效。输入已保留，请重新质检。';$('confirm-board').disabled=true;document.querySelectorAll('[data-generate-video]').forEach(b=>b.disabled=true);}
function generateBoard(){const run=()=>{if(s.shots.length)s.history.push({boardVersion:s.boardVersion,scriptId:s.boardScriptId,shots:clone(s.shots)});s.shots=makeShots(s);s.boardScriptId=s.final.id;changed(s);s.report=null;s.jobs.push(taskSnapshot(s,'storyboard'));persist();render();toast('已生成 3 镜头演示分镜；包含一个动作衔接问题供质检演示')};if(s.shots.length)confirmAction('重新生成整份分镜？','当前分镜和素材将归档为旧版本，新版以当前选定剧本为输入。',run);else run();}
function review(){if(boardStale(s)){toast('请先按新终版重新生成分镜');return}const pending={baseBoardVersion:s.boardVersion,scriptId:s.final.id,snapshot:taskSnapshot(s,'review'),shots:clone(s.shots)};$('run-review').disabled=true;toast('正在对照选定剧本检查分镜（演示）…');setTimeout(()=>{const issues=pending.shots.filter(sh=>sh.prompt.includes('站在门口，将包裹递给老师')).map(sh=>({shotId:sh.id,type:'动作逻辑',severity:'需调整',evidence:'选定剧本包含先取出包裹再递交的动作。',before:sh.prompt,after:'快递员从车后取出被雨衣护住的包裹，走到门口，双手递给老师。镜头跟随取件与递交，保持克制感激的情绪。'}));s.report={schemaVersion:1,scriptId:pending.scriptId,baseBoardVersion:pending.baseBoardVersion,issues,proposedShots:pending.shots.map(sh=>({id:sh.id,dialogue:sh.dialogue,prompt:issues.find(x=>x.shotId===sh.id)?.after||sh.prompt})),snapshot:pending.snapshot};persist();render();showReport()},500);}
function showReport(){const r=s.report;if(!r)return;const expired=r.baseBoardVersion!==s.boardVersion||r.scriptId!==s.final?.id||boardStale(s);const d=$('review-dialog');d.innerHTML=`<div class="panel-header"><div><p class="eyebrow">剧本 ${esc(r.scriptId)} / 分镜 v${r.baseBoardVersion}</p><h2 id="review-title">分镜质检报告与建议版</h2></div><button class="button" id="close-review">关闭</button></div><div class="notice ${expired?'warning':''}">${expired?'报告已过期，禁止采用。请对当前版本重新质检。':`示例检查完成：${r.issues.length} 项问题。检查维度：信息遗漏、情绪错位、动作逻辑。此处仅演示报告交互，不能代替真实模型或人工审核。`}</div><div class="row"><button class="button" id="review-prompt">质检提示词</button><span class="pill">JSON 结构校验 + 版本校验</span></div><div class="report-scroll">${r.issues.map(x=>`<section class="review-box"><h3>${esc(x.shotId)} · ${esc(x.type)}</h3><p>${esc(x.evidence)}</p><div class="diff"><div><p class="diff-title">当前版</p><p class="diff-text">${esc(x.before)}</p></div><div><p class="diff-title">建议调整版</p><p class="diff-text">${esc(x.after)}</p></div></div></section>`).join('')||'<p>本次演示未返回问题。可关闭报告并人工确认当前分镜。</p>'}<details><summary>建议调整版 · 全部镜头</summary>${r.proposedShots.map(sh=>`<p><strong>${esc(sh.id)}</strong> · ${esc(sh.dialogue)}<br>${esc(sh.prompt)}</p>`).join('')}</details><details><summary>查看后台 JSON 交换示例</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details></div><div class="dialog-footer"><button class="button primary" id="apply-review" ${expired||!r.issues.length?'disabled':''}>一键采用建议版</button></div><p class="helper">采用后将当前分镜更新为建议版，旧版归档；只替换允许的文本字段，图片与视频保留，受影响素材需重新确认。修改后必须复检。</p>`;action('close-review',()=>d.close());action('review-prompt',()=>{d.close();openSettings('prompts','review')});action('apply-review',()=>{try{applyReport(s);persist();d.close();render();toast('已采用建议版并保留旧版。请重新质检，再确认分镜。')}catch(e){toast(e.message)}});d.showModal();}
function imagePreview(name){return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="320" height="200" viewBox="0 0 320 200"><rect width="320" height="200" fill="#d8dfe5"/><rect x="60" y="30" width="200" height="140" rx="8" fill="#33465a"/><circle cx="160" cy="68" r="24" fill="#d7bfa9"/><path d="M105 150Q110 98 160 99Q210 98 215 150" fill="#8095a7"/><text x="160" y="188" font-size="14" text-anchor="middle" fill="#24374b">参考图占位示意 · 非 AI 输出</text></svg>`)}
function fileRead(file,max,done){if(!file)return;if(file.size>max){toast(`演示文件上限 ${max/1024/1024} MB，请选择更小文件`);return}const reader=new FileReader();reader.onload=()=>done(reader.result);reader.onerror=()=>toast('文件读取失败，请重试');reader.readAsDataURL(file)}
function bindBoard(){action('generate-board',generateBoard);action('run-review',review);action('view-report',showReport);action('confirm-board',()=>{try{validateReport(s.report,s);if(s.report.issues.length)throw Error('请先处理质检问题');s.boardConfirmed=s.boardVersion;persist();render();toast('当前分镜已人工确认')}catch(e){toast(e.message)}});document.querySelectorAll('[data-shot-field]').forEach(e=>e.onchange=()=>{const[i,k]=e.dataset.shotField.split(':');if(k==='duration'&&(!Number.isFinite(+e.value)||+e.value<1||+e.value>90)){toast('演示时长请输入 1–90 秒');e.value=s.shots[i].duration;return}s.shots[i][k]=k==='duration'?+e.value:e.value;editShot(+i)});document.querySelectorAll('[data-ai-dialogue]').forEach(b=>b.onclick=()=>{const i=+b.dataset.aiDialogue;s.shots[i].dialogue='老师，这份感谢，我一直想亲口告诉您。';editShot(i);render();toast('已填入可编辑台词示例')});document.querySelectorAll('[data-ai-prompt]').forEach(b=>b.onclick=()=>{const i=+b.dataset.aiPrompt;s.shots[i].prompt+='\n示例补充：中景平视，镜头缓慢推进，保持角色外观和场景光线一致。';editShot(i);render();toast('已补入可编辑提示词示例')});document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const[i,n]=b.dataset.move.split(':').map(Number);[s.shots[i],s.shots[i+n]]=[s.shots[i+n],s.shots[i]];changed(s);persist();render()});document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{const i=+b.dataset.add;const sh=clone(s.shots[i]);sh.id=`shot-${Date.now()}`;sh.video=null;sh.videoStale=false;sh.dialogue='';sh.assets.forEach(a=>a.confirmed=false);s.shots.splice(i+1,0,sh);changed(s);persist();render()});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>confirmAction('删除这个镜头？','删除后保存旧分镜版本，当前质检与确认失效。',()=>{s.history.push({boardVersion:s.boardVersion,scriptId:s.boardScriptId,shots:clone(s.shots)});s.shots.splice(+b.dataset.delete,1);changed(s);persist();render()}));
 document.querySelectorAll('[data-manage-asset]').forEach(b=>b.onclick=()=>{const[i,j]=b.dataset.manageAsset.split(':').map(Number),sh=s.shots[i],a=sh.assets[j],d=$('confirm-dialog');
d.innerHTML=`<h2 id="confirm-title">镜头 ${i+1} · ${a.kind}参考图</h2><label class="field">素材名称<input type="text" id="asset-edit-name" value="${esc(a.name)}"></label><label class="field">素材描述<textarea id="asset-edit-description">${esc(a.description)}</textarea></label>${a.image?`<img alt="当前参考图" src="${esc(a.image)}" style="width:100%;height:180px;object-fit:contain">`:'<p>尚无参考图</p>'}<label class="field">上传已有图片<input type="file" id="asset-file" accept="image/png,image/jpeg,image/webp"></label><p class="helper">演示支持 PNG/JPEG/WebP，单图不超过 2 MB。上传只保存本地演示，不发送给模型。</p><div class="dialog-footer"><button class="button" id="manage-close">关闭</button><button class="button" id="manage-save">保存描述</button><button class="button primary" id="manage-confirm" ${a.image?'':'disabled'}>确认选用此图</button></div>`;
action('manage-close',()=>d.close());action('manage-save',()=>{const name=$('asset-edit-name').value.trim(),description=$('asset-edit-description').value;if(!name){toast('素材名称不能为空');return;}if(a.name!==name||a.description!==description){a.name=name;a.description=description;a.confirmed=false;sh.videoStale=!!sh.video;}persist();d.close();render();toast('素材描述已保存；改动后需重新确认图片')});action('manage-confirm',()=>{const name=$('asset-edit-name').value.trim();if(!name){toast('素材名称不能为空');return;}a.name=name;a.description=$('asset-edit-description').value;a.confirmed=true;persist();d.close();render()});$('asset-file').onchange=e=>{const f=e.target.files[0];if(f&&!['image/png','image/jpeg','image/webp'].includes(f.type)){toast('请选择 PNG、JPEG 或 WebP');return}fileRead(f,2*1024*1024,data=>{a.image=data;a.confirmed=false;sh.videoStale=!!sh.video;persist();d.close();render();toast('图片已上传，请打开设置确认选用')})};d.showModal();});
 document.querySelectorAll('[data-asset-name]').forEach(e=>e.onchange=()=>{const[i,j]=e.dataset.assetName.split(':').map(Number);s.shots[i].assets[j].name=e.value;editShot(i)});
 document.querySelectorAll('[data-asset-edit]').forEach(b=>b.onclick=()=>{const[i,j]=b.dataset.assetEdit.split(':').map(Number),a=s.shots[i].assets[j],d=$('confirm-dialog');d.innerHTML=`<h2 id="confirm-title">编辑${a.kind}描述</h2><label class="field">素材描述<textarea id="asset-description">${esc(a.description)}</textarea></label><div class="dialog-footer"><button class="button" id="asset-close">取消</button><button class="button primary" id="asset-save">保存描述</button></div>`;action('asset-close',()=>d.close());action('asset-save',()=>{a.description=$('asset-description').value;a.confirmed=false;s.shots[i].videoStale=!!s.shots[i].video;persist();d.close();render()});d.showModal()});
 function setImage(i,j,data){const sh=s.shots[i];sh.assets[j].image=data;sh.assets[j].confirmed=false;sh.videoStale=!!sh.video;persist();render();toast('参考图已放入镜头，需人工确认选用')}
 document.querySelectorAll('[data-asset-generate]').forEach(b=>b.onclick=()=>{const[i,j]=b.dataset.assetGenerate.split(':').map(Number);s.jobs.push(taskSnapshot(s,'image'));setImage(i,j,imagePreview(s.shots[i].assets[j].name))});document.querySelectorAll('[data-asset-upload]').forEach(e=>e.onchange=()=>{const[i,j]=e.dataset.assetUpload.split(':').map(Number),f=e.files[0];if(f&&!['image/png','image/jpeg','image/webp'].includes(f.type)){toast('请选择 PNG、JPEG 或 WebP 图片');return}fileRead(f,2*1024*1024,data=>setImage(i,j,data))});document.querySelectorAll('[data-asset-confirm]').forEach(b=>b.onclick=()=>{const[i,j]=b.dataset.assetConfirm.split(':').map(Number);s.shots[i].assets[j].confirmed=true;persist();render()});
 document.querySelectorAll('[data-generate-video]').forEach(b=>b.onclick=()=>{const i=+b.dataset.generateVideo,shot=s.shots[i],snapshot={...taskSnapshot(s,'video'),assetSignature:JSON.stringify(shot.assets)};b.disabled=true;b.textContent='生成中…';setTimeout(()=>{shot.video={kind:'demo',snapshot};shot.videoStale=s.boardVersion!==snapshot.boardVersion||s.styleVersion!==snapshot.styleVersion||s.final?.id!==snapshot.scriptId||snapshot.assetSignature!==JSON.stringify(shot.assets);persist();render();toast('镜头生成流程演示完成；未调用模型、未产生真实视频')},650)});document.querySelectorAll('[data-video-upload]').forEach(e=>e.onchange=()=>{const f=e.files[0];if(f&&!['video/mp4','video/webm'].includes(f.type)){toast('请选择 MP4 或 WebM 视频');return}fileRead(f,3*1024*1024,data=>{const sh=s.shots[+e.dataset.videoUpload];sh.video={kind:'upload',data,snapshot:taskSnapshot(s,'video')};sh.videoStale=false;persist();render()})});}
function timeline(){const order=s.finishing.order||s.shots.map(sh=>sh.id);return [...order,...s.shots.map(sh=>sh.id).filter(id=>!order.includes(id))].map(id=>s.shots.find(sh=>sh.id===id)).filter(Boolean).map(sh=>({...sh,duration:s.finishing.durations?.[sh.id]??sh.duration}));}
function finishPage(){const missing=s.shots.filter(sh=>!sh.video||sh.videoStale);const ready=s.shots.length&&s.boardConfirmed===s.boardVersion&&!boardStale(s)&&!missing.length&&s.shots.every(sh=>sh.assets.every(a=>a.confirmed));return `<div class="page-heading"><div><p class="eyebrow">一句话 → 短片 / 03</p><h1>成片与导出</h1><p>检查镜头顺序、时长和声音，预览后交付。</p></div><span class="pill">合计 ${timeline().reduce((n,sh)=>n+sh.duration,0)} 秒 · 9:16</span></div><div class="notice ${ready?'success':'warning'}" id="export-check">${ready?'演示素材检查通过。仍需实际音画预览与生产合成验收。':`尚未满足导出条件：${!s.shots.length?'没有分镜；':''}${s.boardConfirmed!==s.boardVersion?'分镜未确认；':''}${boardStale(s)?'剧本来源过期；':''}${missing.length?missing.map(sh=>sh.id).join('、')+' 缺少视频或视频待更新；':''}${s.shots.some(sh=>sh.assets.some(a=>!a.confirmed))?'参考图尚未全部确认。':''}`}<a href="./storyboard.html" data-nav="storyboard">返回分镜处理</a></div><div class="finish-layout"><section class="panel"><h2>镜头顺序与时长</h2>${timeline().map((sh,i)=>`<div class="finish-row"><div><strong>${i+1} · ${esc(sh.id)}</strong><p>${esc(sh.dialogue)}</p></div><label class="field">秒<input type="number" min="1" max="90" data-finish-duration="${i}" value="${sh.duration}"></label><div class="row"><button class="button" data-finish-move="${i}:-1" ${i===0?'disabled':''}>上移</button><button class="button" data-finish-move="${i}:1" ${i===s.shots.length-1?'disabled':''}>下移</button></div></div>`).join('')||'<p>完成剧本与分镜后，这里显示镜头。</p>'}<h2 style="margin-top:20px">声音与字幕</h2><div class="field-pair"><label class="field">配音方向<input type="text" id="finish-voice" value="${esc(s.finishing.voice)}"></label><label class="field">配乐方向<input type="text" id="finish-music" value="${esc(s.finishing.music)}"></label></div><label class="check"><input type="checkbox" id="finish-subtitle" ${s.finishing.subtitles?'checked':''}>包含字幕</label><div class="row"><button class="button" data-config="prompts" data-step="voice">配音提示词</button><button class="button" data-config="prompts" data-step="music">配乐提示词</button><button class="button" data-config="prompts" data-step="subtitle">字幕提示词</button><button class="button" id="sound-demo">生成声音方案（演示）</button></div><p id="sound-status" class="helper">原型仅保存声音方向；不生成真实音频。</p><div class="row" style="margin-top:20px"><button class="button primary" id="export-demo" ${ready?'':'disabled'}>导出成片（演示）</button><button class="button" id="download-plan">下载制作清单 JSON</button></div><p id="export-status" role="status"></p></section><aside class="panel" id="finish-preview"><h2>分镜顺序预览</h2><p class="helper">按镜头轮播演示，每镜头展示 2 秒；不是最终合成视频。</p><div class="preview-frame" id="preview-frame"><p>点击开始，检查镜头叙述顺序。</p></div><button class="button" id="play-preview" ${s.shots.length?'':'disabled'}>开始预览</button></aside></div>`}
function bindFinish(){action('sound-demo',()=>{$('sound-status').textContent=`声音方案已保存：${s.finishing.voice} / ${s.finishing.music}，${s.finishing.subtitles?'包含':'不包含'}字幕。此处无真实音频输出。`;persist()});for(const[k,id]of [['voice','finish-voice'],['music','finish-music']])$(id).oninput=e=>{s.finishing[k]=e.target.value;persist()};$('finish-subtitle').onchange=e=>{s.finishing.subtitles=e.target.checked;persist()};document.querySelectorAll('[data-finish-duration]').forEach(e=>e.onchange=()=>{if(+e.value<1||+e.value>90){toast('请输入 1–90 秒');e.value=timeline()[+e.dataset.finishDuration].duration;return}const sh=timeline()[+e.dataset.finishDuration];s.finishing.durations??={};s.finishing.durations[sh.id]=+e.value;persist();render();toast('时长已调整，请重新预览并检查字幕与声音同步')});document.querySelectorAll('[data-finish-move]').forEach(b=>b.onclick=()=>{const[i,n]=b.dataset.finishMove.split(':').map(Number);const list=timeline().map(sh=>sh.id);[list[i],list[i+n]]=[list[i+n],list[i]];s.finishing.order=list;persist();render();toast('顺序已调整，请重新检查叙事与音画同步')});action('play-preview',()=>{clearInterval(previewTimer);let i=0;const show=()=>{const sh=timeline()[i%s.shots.length];$('preview-frame').innerHTML=`<h3>镜头 ${i%s.shots.length+1}</h3><p>${esc(sh.prompt)}</p>${s.finishing.subtitles?`<p>「${esc(sh.dialogue)}」</p>`:''}`;i++;};show();previewTimer=setInterval(()=>{if(i>=s.shots.length){clearInterval(previewTimer);$('play-preview').textContent='重新预览';return}show()},2000);$('play-preview').textContent='预览中 / 点击重播'});action('export-demo',()=>{$('export-demo').disabled=true;$('export-status').textContent='演示：合成排队 → 正在合成…';setTimeout(()=>{$('export-status').textContent='导出流程演示完成。当前未接入编码或模型服务，不生成 MP4；可下载制作清单用于评审。';$('export-demo').disabled=false},700)});action('download-plan',()=>{const data={demo:true,title:s.title,script:s.final,boardVersion:s.boardVersion,shots:timeline().map(({id,dialogue,prompt,duration,assets})=>({id,dialogue,prompt,duration,assets:assets.map(({kind,name,description,confirmed})=>({kind,name,description,confirmed}))})),finishing:s.finishing};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='mengyuan-production-plan-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});}
render();
